for (int i = 0; i < 5; i++) {
    System.out.println("Start: " + i);
    if (i == 2) {
        continue;  // Skips lines below
    }
    System.out.println("End: " + i);
}
// At i=2: prints "Start: 2" then skips "End: 2"
```

