// Efficient prime checker method
public static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;

    for (int i = 3; i <= Math.sqrt(n); i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

// Usage
for (int num = 1; num <= 100; num++) {
    if (isPrime(num)) {
        System.out.print(num + " ");
    }
}

